  watchPath: {
    key: "watchPath",
    name: "WatchPath",
    description:
      "Watch a file or directory for changes for a bounded time and report what happened. Use it instead of sleeping and re-reading: it ends at whichever comes first of a required deadline and an event cap, and always says which one, so an empty answer cannot be mistaken for a satisfied wait. Events for the same path within a settle window fold into ONE event that reports how many raw notifications it absorbed — an editor writes a file two or three times to save it once, and most editors save by writing a temp file and renaming it over the target, so a caller counting raw notifications counts several saves where there was one. The kind (created, modified, deleted) is derived from the filesystem rather than from the platform's own event name, because macOS calls an ordinary append a 'rename'. On Linux a file created inside a directory that was itself created during the watch may be missed, and the result says so rather than implying the tree was covered.",
    readOnly: true,
    destructive: false,
    scope: "internal",
    requiresSandbox: false,
    requireJustification: false,
    categories: ["filesystem", "hostfs"],
    package: "@crewhaus/tool-hostfs",
    keywords: ["watch a file", "file changes", "observe directory", "fs events"],
  },
  watchmeReport: {
    key: "watchmeReport",
    name: "WatchmeReport",
    description:
      "Read a harness's observational-learning ledger: whether it is watching, the per-window report outcomes, the per-spec/target quality and cost roll-up, the judge verdicts, and how much of that quality has actually reached the routing scoreboard's observe-only `q:` lane. Report-window outcomes are kept apart — `model_refused_unpriced` is a configuration error that consumed its window, `model_failed` is transient and retries, and collapsing them into one failure state hides the first as the second. A state.json that exists but cannot be parsed is reported as unreadable, never as a harness that has never watched: the store falls back to its default there, which reads as the opposite of the truth. The routing half degrades explicitly — an absent or unreadable scoreboard is reported as such, never as 'no quality signal'. Every rate carries a Wilson interval. Read-only: it never runs the phase-2 judge, never synthesizes, and never feeds routing.",
    readOnly: true,
    destructive: false,
    scope: "internal",
    requiresSandbox: false,
    requireJustification: false,
    categories: ["operations", "routing"],
    package: "@crewhaus/tool-routing",
    keywords: ["watchme", "observational learning", "co-learning", "recall"],
  },
